"""Cluster deployment manifest definitions."""
from dataclasses import dataclass, field
from typing import Dict, Any, List

@dataclass
class ClusterManifest:
    cluster_id: str
    spec: Dict[str, Any]
    status: str = "pending"

    def get_node_zones(self) -> List[str]:
        base_zones = self.spec.get("zones", [])
        tenant_zones = self.spec.get("tenant_zones", [])
        return list(set(base_zones + tenant_zones))

    def to_payload(self) -> Dict[str, Any]:
        return {
            "cluster_id": self.cluster_id,
            "spec": self.spec,
            "status": self.status
        }
